const e=JSON.parse('{"key":"v-44d2e7ae","path":"/posts/ai-tech/%E4%BB%8B%E7%BB%8D%E4%B8%80%E4%B8%AA%E8%B6%85%E7%9B%B4%E8%A7%82%E7%9A%84%20Token%20%E5%8F%AF%E8%A7%86%E5%8C%96%E5%B7%A5%E5%85%B7%EF%BC%9ATiktokenizer.html","title":"","lang":"zh-CN","frontmatter":{"description":"很多人刚开始学习大模型时，都会默认一个理解： 我们输入一段文字，GPT 就是在“读”这段文字。 比如你问它： What is c plus plus 从人的角度看，这就是一句普通的问题。 但从模型的角度看，事情并没有这么简单。 GPT 并不是直接处理原始文字。 在文字真正进入模型之前，会先经过一个非常关键的步骤： Tokenization，也就是分词。 简单来说，Tokenizer 会先把文本切成一个个 Token，然后再把每个 Token 转换成对应的数字编号，也就是 Token ID。","head":[["meta",{"property":"og:url","content":"https://mister-hope.github.io/posts/ai-tech/%E4%BB%8B%E7%BB%8D%E4%B8%80%E4%B8%AA%E8%B6%85%E7%9B%B4%E8%A7%82%E7%9A%84%20Token%20%E5%8F%AF%E8%A7%86%E5%8C%96%E5%B7%A5%E5%85%B7%EF%BC%9ATiktokenizer.html"}],["meta",{"property":"og:site_name","content":"Code Building"}],["meta",{"property":"og:description","content":"很多人刚开始学习大模型时，都会默认一个理解： 我们输入一段文字，GPT 就是在“读”这段文字。 比如你问它： What is c plus plus 从人的角度看，这就是一句普通的问题。 但从模型的角度看，事情并没有这么简单。 GPT 并不是直接处理原始文字。 在文字真正进入模型之前，会先经过一个非常关键的步骤： Tokenization，也就是分词。 简单来说，Tokenizer 会先把文本切成一个个 Token，然后再把每个 Token 转换成对应的数字编号，也就是 Token ID。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-05-25T07:00:06.000Z"}],["meta",{"property":"article:modified_time","content":"2026-05-25T07:00:06.000Z"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-05-25T07:00:06.000Z\\",\\"author\\":[]}"]]},"headers":[],"git":{"createdTime":1779692406000,"updatedTime":1779692406000,"contributors":[{"name":"zgjsxx","email":"119160524@qq.com","commits":1}]},"readingTime":{"minutes":4.49,"words":1347},"filePathRelative":"posts/ai-tech/介绍一个超直观的 Token 可视化工具：Tiktokenizer.md","localizedDate":"2026年5月25日","excerpt":"<p>很多人刚开始学习大模型时，都会默认一个理解：</p>\\n<p>我们输入一段文字，GPT 就是在“读”这段文字。</p>\\n<p>比如你问它：</p>\\n<p>What is c plus plus</p>\\n<p>从人的角度看，这就是一句普通的问题。<br>\\n但从模型的角度看，事情并没有这么简单。</p>\\n<p>GPT 并不是直接处理原始文字。<br>\\n在文字真正进入模型之前，会先经过一个非常关键的步骤：</p>\\n<p><strong>Tokenization，也就是分词。</strong></p>\\n<p>简单来说，Tokenizer 会先把文本切成一个个 <strong>Token</strong>，然后再把每个 Token 转换成对应的数字编号，也就是 <strong>Token ID</strong>。</p>","autoDesc":true}');export{e as data};
